{
  "name": "AudioStudio Pro",
  "description": "Een krachtige, client-side audio editor voor het bewerken, knippen en exporteren van audiobestanden direct in de browser.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { Editor } from './components/Editor';
import { WelcomeScreen } from './components/WelcomeScreen';
import { FileData } from './types';

export default function App() {
  const [fileData, setFileData] = useState<FileData | null>(null);

  const handleFileSelect = (file: File) => {
    const objectUrl = URL.createObjectURL(file);
    setFileData({
      file,
      url: objectUrl,
      name: file.name,
      type: file.type
    });
  };

  const handleReset = () => {
    if (fileData?.url) {
      URL.revokeObjectURL(fileData.url);
    }
    setFileData(null);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 text-slate-100">
      <header className="flex-none h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 text-white">
              <path fillRule="evenodd" d="M19.952 1.651a.75.75 0 01.298.599V16.303a3 3 0 01-2.176 2.884l-1.32.377a2.553 2.553 0 11-1.403-4.909l2.311-.66a1.5 1.5 0 001.088-1.442V6.994l-9 2.572v9.737a3 3 0 01-2.176 2.884l-1.32.377a2.553 2.553 0 11-1.402-4.909l2.31-.66a1.5 1.5 0 001.088-1.442V9.017 5.25a.75.75 0 01.544-.721l10.5-3a.75.75 0 01.658.122z" clipRule="evenodd" />
            </svg>
          </div>
          <h1 className="font-bold text-lg tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
            AudioStudio <span className="text-indigo-400 font-medium">Pro</span>
          </h1>
        </div>

        {fileData && (
          <button 
            onClick={handleReset}
            className="text-xs font-medium text-slate-400 hover:text-white transition-colors flex items-center gap-2 bg-slate-800/50 hover:bg-slate-800 px-3 py-1.5 rounded-full border border-slate-700"
          >
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM6.75 9.25a.75.75 0 000 1.5h4.59l-2.1 1.95a.75.75 0 001.02 1.1l3.5-3.25a.75.75 0 000-1.1l-3.5-3.25a.75.75 0 10-1.02 1.1l2.1 1.95H6.75z" clipRule="evenodd" />
            </svg>
            Nieuw Project
          </button>
        )}
      </header>

      <main className="flex-1 overflow-hidden relative">
        {fileData ? (
          <Editor fileData={fileData} />
        ) : (
          <WelcomeScreen onFileSelect={handleFileSelect} />
        )}
      </main>
    </div>
  );
}

export interface FileData {
  file: File;
  url: string;
  name: string;
  type: string;
}

export interface Region {
  id: string;
  start: number;
  end: number;
  color?: string;
}

export interface AudioStats {
  duration: number;
  sampleRate: number;
  channels: number;
}

/**
 * Converts an AudioBuffer to a WAV format Blob.
 */
export function bufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;

  let result: Float32Array;
  if (numChannels === 2) {
    result = interleave(buffer.getChannelData(0), buffer.getChannelData(1));
  } else {
    result = buffer.getChannelData(0);
  }

  return encodeWAV(result, numChannels, sampleRate, format, bitDepth);
}

function interleave(inputL: Float32Array, inputR: Float32Array) {
  const length = inputL.length + inputR.length;
  const result = new Float32Array(length);

  let index = 0;
  let inputIndex = 0;

  while (index < length) {
    result[index++] = inputL[inputIndex];
    result[index++] = inputR[inputIndex];
    inputIndex++;
  }
  return result;
}

function encodeWAV(
  samples: Float32Array,
  numChannels: number,
  sampleRate: number,
  format: number,
  bitDepth: number
) {
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;

  const buffer = new ArrayBuffer(44 + samples.length * bytesPerSample);
  const view = new DataView(buffer);

  /* RIFF identifier */
  writeString(view, 0, 'RIFF');
  /* RIFF chunk length */
  view.setUint32(4, 36 + samples.length * bytesPerSample, true);
  /* RIFF type */
  writeString(view, 8, 'WAVE');
  /* format chunk identifier */
  writeString(view, 12, 'fmt ');
  /* format chunk length */
  view.setUint32(16, 16, true);
  /* sample format (raw) */
  view.setUint16(20, format, true);
  /* channel count */
  view.setUint16(22, numChannels, true);
  /* sample rate */
  view.setUint32(24, sampleRate, true);
  /* byte rate (sample rate * block align) */
  view.setUint32(28, sampleRate * blockAlign, true);
  /* block align (channel count * bytes per sample) */
  view.setUint16(32, blockAlign, true);
  /* bits per sample */
  view.setUint16(34, bitDepth, true);
  /* data chunk identifier */
  writeString(view, 36, 'data');
  /* data chunk length */
  view.setUint32(40, samples.length * bytesPerSample, true);

  floatTo16BitPCM(view, 44, samples);

  return new Blob([view], { type: 'audio/wav' });
}

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function floatTo16BitPCM(output: DataView, offset: number, input: Float32Array) {
  for (let i = 0; i < input.length; i++, offset += 2) {
    const s = Math.max(-1, Math.min(1, input[i]));
    output.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7FFF, true);
  }
}

/**
 * Creates a new AudioBuffer containing a specific slice of the original buffer.
 */
export function sliceAudioBuffer(
  originalBuffer: AudioBuffer,
  start: number,
  end: number,
  audioContext: AudioContext
): AudioBuffer {
  const channels = originalBuffer.numberOfChannels;
  const rate = originalBuffer.sampleRate;

  // Calculate start/end frames
  const startOffset = Math.floor(start * rate);
  const endOffset = Math.floor(end * rate);
  const frameCount = endOffset - startOffset;

  if (frameCount <= 0) return originalBuffer;

  const newBuffer = audioContext.createBuffer(channels, frameCount, rate);

  for (let i = 0; i < channels; i++) {
    const channelData = originalBuffer.getChannelData(i);
    const slicedData = channelData.slice(startOffset, endOffset);
    newBuffer.copyToChannel(slicedData, i);
  }

  return newBuffer;
}

/**
 * Creates a new AudioBuffer with the specified region removed (Cut).
 */
export function removeRegionFromBuffer(
  originalBuffer: AudioBuffer,
  start: number,
  end: number,
  audioContext: AudioContext
): AudioBuffer {
  const channels = originalBuffer.numberOfChannels;
  const rate = originalBuffer.sampleRate;

  const startOffset = Math.floor(start * rate);
  const endOffset = Math.floor(end * rate);
  const lengthToRemove = endOffset - startOffset;
  const newLength = originalBuffer.length - lengthToRemove;

  if (newLength <= 0) return originalBuffer; // Should typically not happen unless deleting everything

  const newBuffer = audioContext.createBuffer(channels, newLength, rate);

  for (let i = 0; i < channels; i++) {
    const originalData = originalBuffer.getChannelData(i);
    const newData = new Float32Array(newLength);

    // Part 1: Before cut
    newData.set(originalData.slice(0, startOffset), 0);

    // Part 2: After cut
    newData.set(originalData.slice(endOffset), startOffset);

    newBuffer.copyToChannel(newData, i);
  }

  return newBuffer;
}

import React, { useCallback } from 'react';

interface WelcomeScreenProps {
  onFileSelect: (file: File) => void;
}

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ onFileSelect }) => {
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      const files = e.dataTransfer.files;
      if (files && files[0] && files[0].type.startsWith('audio/')) {
        onFileSelect(files[0]);
      }
    },
    [onFileSelect]
  );

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileSelect(e.target.files[0]);
    }
  };

  return (
    <div className="flex h-full w-full items-center justify-center p-6">
      <div 
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        className="group relative flex flex-col items-center justify-center w-full max-w-2xl h-96 rounded-3xl border-2 border-dashed border-slate-700 bg-slate-900/50 hover:bg-slate-900 hover:border-indigo-500/50 transition-all duration-300 cursor-pointer"
      >
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-purple-500/5 rounded-3xl pointer-events-none" />

        <div className="z-10 flex flex-col items-center space-y-4">
          <div className="p-4 rounded-full bg-slate-800 group-hover:bg-indigo-500/10 group-hover:scale-110 transition-all duration-300">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-indigo-400">
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" />
            </svg>
          </div>

          <div className="text-center">
            <h2 className="text-2xl font-bold text-slate-200">Sleep audio hierheen</h2>
            <p className="text-slate-400 mt-2">of klik om een bestand te selecteren</p>
            <p className="text-xs text-slate-500 mt-1 uppercase tracking-wider">MP3, WAV, OGG</p>
          </div>
        </div>

        <input
          type="file"
          accept="audio/*"
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
          onChange={handleInputChange}
        />
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import TimelinePlugin from 'wavesurfer.js/dist/plugins/timeline.esm.js';
import ZoomPlugin from 'wavesurfer.js/dist/plugins/zoom.esm.js';
import { FileData, AudioStats } from '../types';
import { bufferToWav, sliceAudioBuffer, removeRegionFromBuffer } from '../utils/audioUtils';

interface EditorProps {
  fileData: FileData;
}

export const Editor: React.FC<EditorProps> = ({ fileData }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const [ws, setWs] = useState<WaveSurfer | null>(null);
  const [regionsPlugin, setRegionsPlugin] = useState<RegionsPlugin | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [zoom, setZoom] = useState(10);
  const [volume, setVolume] = useState(1);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [stats, setStats] = useState<AudioStats | null>(null);
  const [activeRegion, setActiveRegion] = useState<boolean>(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !timelineRef.current) return;

    const wsInstance = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1', // Indigo 500
      progressColor: '#a5b4fc', // Indigo 300
      cursorColor: '#f8fafc', // Slate 50
      cursorWidth: 2,
      barWidth: 2,
      barGap: 3,
      barRadius: 3,
      height: 250,
      minPxPerSec: zoom,
      normalize: true,
      url: fileData.url,
      interact: true,
    });

    const regions = RegionsPlugin.create();
    wsInstance.registerPlugin(regions);

    wsInstance.registerPlugin(TimelinePlugin.create({
      container: timelineRef.current,
      primaryLabelColor: '#94a3b8',
      secondaryLabelColor: '#475569',
      style: {
        fontSize: '12px',
      }
    }));

    wsInstance.registerPlugin(ZoomPlugin.create());

    wsInstance.on('ready', () => {
      // Decode audio data for manual processing later
      const audioCtx = new AudioContext();
      fetch(fileData.url)
        .then(res => res.arrayBuffer())
        .then(arrayBuffer => audioCtx.decodeAudioData(arrayBuffer))
        .then(decodedBuffer => {
          setAudioBuffer(decodedBuffer);
          setStats({
            duration: decodedBuffer.duration,
            sampleRate: decodedBuffer.sampleRate,
            channels: decodedBuffer.numberOfChannels
          });
        });
    });

    wsInstance.on('play', () => setIsPlaying(true));
    wsInstance.on('pause', () => setIsPlaying(false));
    wsInstance.on('finish', () => setIsPlaying(false));

    regions.on('region-created', (region) => {
      // Ensure only one region exists at a time for simplicity
      regions.getRegions().forEach(r => {
        if (r.id !== region.id) r.remove();
      });
      setActiveRegion(true);
    });

    regions.on('region-removed', () => {
      if (regions.getRegions().length === 0) {
        setActiveRegion(false);
      }
    });

    setWs(wsInstance);
    setRegionsPlugin(regions);

    return () => {
      wsInstance.destroy();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fileData.url]); // Re-init only if URL changes

  // Update zoom when state changes
  useEffect(() => {
    if (ws) {
      ws.zoom(zoom);
    }
  }, [zoom, ws]);

  // Update volume
  useEffect(() => {
    if (ws) {
      ws.setVolume(volume);
    }
  }, [volume, ws]);

  const togglePlay = useCallback(() => {
    ws?.playPause();
  }, [ws]);

  const stop = useCallback(() => {
    ws?.stop();
    ws?.seekTo(0);
  }, [ws]);

  const clearRegions = useCallback(() => {
    regionsPlugin?.getRegions().forEach(r => r.remove());
  }, [regionsPlugin]);

  const reloadBuffer = async (newBuffer: AudioBuffer) => {
    setIsProcessing(true);
    setAudioBuffer(newBuffer);

    // Convert to wav blob to reload into wavesurfer
    const wavBlob = bufferToWav(newBuffer);
    const newUrl = URL.createObjectURL(wavBlob);

    // Load new blob into wavesurfer
    await ws?.load(newUrl);

    setStats({
      duration: newBuffer.duration,
      sampleRate: newBuffer.sampleRate,
      channels: newBuffer.numberOfChannels
    });

    clearRegions();
    setIsProcessing(false);
  };

  const handleTrim = async () => {
    const regions = regionsPlugin?.getRegions();
    if (!regions || regions.length === 0 || !audioBuffer) return;

    const region = regions[0];
    const audioCtx = new AudioContext();
    const newBuffer = sliceAudioBuffer(audioBuffer, region.start, region.end, audioCtx);
    await reloadBuffer(newBuffer);
  };

  const handleCut = async () => {
    const regions = regionsPlugin?.getRegions();
    if (!regions || regions.length === 0 || !audioBuffer) return;

    const region = regions[0];
    const audioCtx = new AudioContext();
    const newBuffer = removeRegionFromBuffer(audioBuffer, region.start, region.end, audioCtx);
    await reloadBuffer(newBuffer);
  };

  const handleDownload = () => {
    if (!audioBuffer) return;
    const wavBlob = bufferToWav(audioBuffer);
    const url = URL.createObjectURL(wavBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `edited-${fileData.name.replace(/\.[^/.]+$/, "")}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="h-full flex flex-col">
      {/* Waveform Area */}
      <div className="flex-1 bg-slate-900/30 p-8 flex flex-col justify-center relative overflow-hidden">
         {isProcessing && (
           <div className="absolute inset-0 z-50 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center">
             <div className="flex flex-col items-center gap-3">
               <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
               <span className="text-slate-300 font-medium">Bezig met verwerken...</span>
             </div>
           </div>
         )}

        <div className="bg-slate-900 rounded-2xl border border-slate-800 shadow-2xl p-6 relative">
          <div ref={containerRef} className="w-full" />
          <div ref={timelineRef} className="w-full mt-2" />
        </div>

        {/* Quick Stats */}
        {stats && (
           <div className="flex justify-center gap-8 mt-4 text-xs font-mono text-slate-500">
             <span>{stats.duration.toFixed(2)}s</span>
             <span>{stats.sampleRate} Hz</span>
             <span>{stats.channels === 2 ? 'Stereo' : 'Mono'}</span>
           </div>
        )}
      </div>

      {/* Controls Area */}
      <div className="flex-none bg-slate-900 border-t border-slate-800 p-6 pb-8">
        <div className="max-w-6xl mx-auto flex flex-col gap-6">

          {/* Top Row: Playback & Volume */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <button 
                 onClick={togglePlay}
                 className="h-14 w-14 rounded-full bg-indigo-600 hover:bg-indigo-500 text-white flex items-center justify-center shadow-lg shadow-indigo-500/30 transition-all hover:scale-105 active:scale-95"
               >
                 {isPlaying ? (
                    <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" className="w-6 h-6">
                      <path d="M6 4h4v16H6V4zm8 0h4v16h-4V4z"/>
                    </svg>
                 ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" className="w-6 h-6 ml-1">
                      <path d="M8 5v14l11-7z"/>
                    </svg>
                 )}
               </button>
               <button onClick={stop} className="p-3 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" className="w-6 h-6">
                    <path d="M6 6h12v12H6z"/>
                  </svg>
               </button>
            </div>

            <div className="flex items-center gap-6 bg-slate-800/50 rounded-xl px-6 py-3 border border-slate-800">
               {/* Zoom Control */}
               <div className="flex items-center gap-3">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 text-slate-400">
                   <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607zM10.5 7.5v6m3-3h-6" />
                 </svg>
                 <input 
                   type="range" 
                   min="10" 
                   max="200" 
                   value={zoom} 
                   onChange={(e) => setZoom(Number(e.target.value))}
                   className="w-32 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                 />
               </div>

               <div className="w-px h-6 bg-slate-700"></div>

               {/* Volume Control */}
               <div className="flex items-center gap-3">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 text-slate-400">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
                  </svg>
                  <input 
                   type="range" 
                   min="0" 
                   max="1" 
                   step="0.01"
                   value={volume} 
                   onChange={(e) => setVolume(Number(e.target.value))}
                   className="w-24 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                 />
               </div>
            </div>
          </div>

          {/* Bottom Row: Actions */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <div className="flex items-center gap-2">
                <button
                  onClick={handleTrim}
                  disabled={!activeRegion}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-semibold rounded-lg border border-slate-700 transition-all"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 7.5h-.75A2.25 2.25 0 004.5 9.75v7.5a2.25 2.25 0 002.25 2.25h7.5a2.25 2.25 0 002.25-2.25v-7.5a2.25 2.25 0 00-2.25-2.25h-.75m0-3l-3-3m0 0l-3 3m3-3v11.25m6-2.25h.75a2.25 2.25 0 012.25 2.25v7.5a2.25 2.25 0 01-2.25 2.25h-7.5a2.25 2.25 0 01-2.25-2.25v-.75" />
                  </svg>
                  Bijsnijden (Trim)
                </button>
                <button
                  onClick={handleCut}
                  disabled={!activeRegion}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-semibold rounded-lg border border-slate-700 transition-all"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                  </svg>
                  Knippen (Cut)
